import * as http from "node:http";
const srv = http.createServer((req, res) => { res.statusCode = 404; res.end(); });
function main(): void {
  const a = Response.json({ a: 1 });
  console.log(a.headers.get("content-type"), a.status);
  const b = Response.redirect("http://a.test/", 301);
  console.log(b.status, b.headers.get("location"));
  console.log(Response.error().type);
  const h = new Headers({ a: "1", b: "2" });
  console.log([...h]);
  srv.listen(0, "127.0.0.1", async () => {
    const c = await fetch(`http://127.0.0.1:${(srv.address() as any).port}/`);
    console.log(c.status, c.ok);
    srv.close();
  });
}
